import { basename } from 'node:path';
import { CliExit, parseCommandLine } from './lib/cli/argparse.mjs';
import { CurrencyDoesNotExist, Money } from './lib/money/money.mjs';

function main() {
  const programName = basename(process.argv[1] ?? 'test10.mjs');
  const { amount, currency } = parseCommandLine(process.argv.slice(2), programName);
  const money = new Money(amount, currency);
  process.stdout.write(`${String(money)}\n`);
}

try {
  main();
} catch (error) {
  if (error instanceof CliExit) {
    if (error.stdout !== '') {
      process.stdout.write(error.stdout);
    }
    if (error.stderr !== '') {
      process.stderr.write(error.stderr);
    }
    process.exitCode = error.code;
  } else if (error instanceof CurrencyDoesNotExist) {
    process.stderr.write(`${error.name}: ${error.message}\n`);
    process.exitCode = 1;
  } else {
    throw error;
  }
}

