);
const SPECIAL_LITERAL = /^[+-]?(?:inf(?:inity)?|nan)$/i;

export class InvalidFloatValueError extends Error {
  constructor(rawValue) {
    super(`invalid float value: '${rawValue}'`);
    this.name = 'InvalidFloatValueError';
    this.rawValue = rawValue;
