export function parsePythonFloatToken(rawValue) {
  if (!isPythonFloatToken(rawValue)) {
    throw new InvalidFloatValueError(rawValue);
  }

  const normalized = rawValue.replaceAll('_', '');
  const lower = normalized.toLowerCase();

  if (lower === 'nan' || lower === '+nan' || lower === '-nan') {
    return { kind: 'nan', negative: false, rawValue };
  }

  if (
    lower === 'inf' ||
    lower === '+inf' ||
    lower === 'infinity' ||
    lower === '+infinity'
  ) {
    return { kind: 'infinity', negative: false, rawValue };
  }

  if (lower === '-inf' || lower === '-infinity') {
    return { kind: 'infinity', negative: true, rawValue };
  }

  const numericValue = Number(normalized);
  if (Number.isNaN(numericValue)) {
    throw new InvalidFloatValueError(rawValue);
  }

  if (!Number.isFinite(numericValue)) {
    return {
      kind: 'infinity',
      negative: normalized.startsWith('-'),
      rawValue,
    };
  }

  const negative = numericValue < 0 || Object.is(numericValue, -0);
  const { integerPart, fractionalPart } = buildFiniteParts(normalized, numericValue);

  return {
    kind: 'finite',
    negative,
    integerPart,
    fractionalPart,
    rawValue,
  };
}

export function formatParsedAmount(parsedAmount, decimalPlaces) {
  if (parsedAmount.kind === 'nan') {
    if (decimalPlaces === 0) {
      return 'NaN';
    }
    return `NaN.${'0'.repeat(decimalPlaces)}`;
  }

  if (parsedAmount.kind === 'infinity') {
    return 'INF';
  }

  const rounded = roundHalfEven(
    parsedAmount.integerPart,
    parsedAmount.fractionalPart,
    decimalPlaces,
  );

  if (decimalPlaces === 0) {
    return rounded.integerPart;
  }

  return `${rounded.integerPart}.${rounded.fractionalPart}`;
}

