import {
  amountHasVisibleNegativeSign,
  formatParsedAmount,
  parsePythonFloatToken,
} from './decimal.mjs';
import { CurrencyDoesNotExist, getCurrencyDefinition } from './currency-data.mjs';

const CURRENCY_AMOUNT_SEPARATOR = '\u00A0';

export class Money {
  constructor(amount, currencyCode) {
    this.amount = typeof amount === 'string' ? parsePythonFloatToken(amount) : amount;
    this.currency = getCurrencyDefinition(currencyCode);
  }

  toString() {
    const sign = amountHasVisibleNegativeSign(this.amount) ? '-' : '';
    const amountText = formatParsedAmount(this.amount, this.currency.decimalPlaces);
    return `${sign}${this.currency.marker}${CURRENCY_AMOUNT_SEPARATOR}${amountText}`;
  }
}

export function formatMoney(amount, currencyCode) {
  return new Money(amount, currencyCode).toString();
}

