import {
  InvalidFloatValueError,
  parsePythonFloatToken,
} from '../money/decimal.mjs';

const HELP_OPTION = {
  longName: '--help',
  shortName: '-h',
  expectsValue: false,
};

const AMOUNT_OPTION = {
  longName: '--amount',
  expectsValue: true,
  valueName: 'AMOUNT',
};

const CURRENCY_OPTION = {
  longName: '--currency',
  expectsValue: true,
  valueName: 'CURRENCY',
};

const LONG_OPTIONS = [HELP_OPTION, AMOUNT_OPTION, CURRENCY_OPTION];
const NEGATIVE_NUMBER_TOKEN = /^-(?:\d+|\d+\.\d+|\.\d+)$/;

export class CliExit extends Error {
  constructor(code, { stdout = '', stderr = '' } = {}) {
    super('CLI exit');
    this.name = 'CliExit';
    this.code = code;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

export function parseCommandLine(argv, programName) {
  let parsedAmount;
  let currency;
  let helpRequested = false;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index));
      break;
    }

    const shortHelpArgument = getShortHelpArgument(token);
    if (shortHelpArgument !== null) {
      throw createArgumentError(
        programName,
        `argument -h/--help: ignored explicit argument '${shortHelpArgument}'`,
      );
    }

    if (isShortHelpToken(token)) {
      helpRequested = true;
      continue;
    }

    const matchedOption = matchLongOption(token);
    if (matchedOption === null) {
      extras.push(token);
      continue;
    }

    if (matchedOption.option === HELP_OPTION) {
      if (matchedOption.inlineValue !== null) {
        throw createArgumentError(
          programName,
          `argument -h/--help: ignored explicit argument '${matchedOption.inlineValue}'`,
        );
      }
      helpRequested = true;
      continue;
    }

    const rawValue =
      matchedOption.inlineValue !== null
        ? matchedOption.inlineValue
        : consumeNextValue(argv, index, matchedOption.option, programName);

    if (matchedOption.inlineValue === null) {
      index += 1;
    }

    if (matchedOption.option === AMOUNT_OPTION) {
      parsedAmount = parseAmountValue(rawValue, programName);
    } else if (matchedOption.option === CURRENCY_OPTION) {
      currency = rawValue;
    }
  }

  if (helpRequested) {
    throw new CliExit(0, { stdout: buildHelpText(programName) });
  }

  const missingArguments = [];
  if (parsedAmount === undefined) {
    missingArguments.push('--amount');
  }
  if (currency === undefined) {
    missingArguments.push('--currency');
  }

  if (missingArguments.length > 0) {
    throw createArgumentError(
      programName,
      `the following arguments are required: ${missingArguments.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    throw createArgumentError(
      programName,
      `unrecognized arguments: ${extras.join(' ')}`,
    );
  }

