function parseAmountValue(rawValue, programName) {
  try {
    return parsePythonFloatToken(rawValue);
  } catch (error) {
    if (error instanceof InvalidFloatValueError) {
      throw createArgumentError(
        programName,
        `argument --amount: invalid float value: '${rawValue}'`,
      );
    }
    throw error;
  }
}

function consumeNextValue(argv, currentIndex, option, programName) {
  const nextValue = argv[currentIndex + 1];
  if (nextValue === undefined) {
    throw createArgumentError(
      programName,
      `argument ${option.longName}: expected one argument`,
    );
  }

  if (nextValue.startsWith('-')) {
    if (option === AMOUNT_OPTION && NEGATIVE_NUMBER_TOKEN.test(nextValue)) {
      return nextValue;
    }

    throw createArgumentError(
      programName,
      `argument ${option.longName}: expected one argument`,
    );
  }

  return nextValue;
}

function matchLongOption(token) {
  if (!token.startsWith('--') || token === '--') {
    return null;
  }

  const equalsIndex = token.indexOf('=');
  const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
  const inlineValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);

  const matchingOptions = LONG_OPTIONS.filter(({ longName }) =>
    longName.startsWith(optionName),
  );

  if (matchingOptions.length !== 1) {
    return null;
  }

  return {
    option: matchingOptions[0],
    inlineValue,
  };
}

