  return /^-h[^=]*$/.test(token);
}

function getShortHelpArgument(token) {
  const match = token.match(/^-h=(.*)$/);
  return match ? match[1] : null;
}

function createArgumentError(programName, message) {
  return new CliExit(2, {
    stderr: `${buildUsageLine(programName)}\n${programName}: error: ${message}\n`,
  });
}

function buildHelpText(programName) {
  return `${buildUsageLine(programName)}\n\noptions:\n  -h, --help           show this help message and exit\n  --amount AMOUNT\n  --currency CURRENCY\n`;
}

function buildUsageLine(programName) {
  return `usage: ${programName} [-h] --amount AMOUNT --currency CURRENCY`;
}

